UPDATE [Станции(архив)] INNER JOIN Станции2020 AS St ON ([Станции(архив)].numb1120 = St.NUMB1120) AND ([Станции(архив)].year = St.YEAR) SET [Станции(архив)].name = St!name, [Станции(архив)].nust = St!nust, [Станции(архив)].nr = St!nr, [Станции(архив)].E = St!e, [Станции(архив)].eotp = St!eotp, [Станции(архив)].eurt = St!eurt, [Станции(архив)].eust = St!eust, [Станции(архив)].Q = St!q, [Станции(архив)].turt = St!turt, [Станции(архив)].tust = St!tust, [Станции(архив)].B = St!b, [Станции(архив)].gaz = St!gaz, [Станции(архив)].isk_gaz = St!isk_gaz, [Станции(архив)].mazut = St!mazut, [Станции(архив)].torf = St!torf, [Станции(архив)].slan = St!slan, [Станции(архив)].proch = St!proch, [Станции(архив)].ugol = St!ugol, [Станции(архив)].don = St!don, [Станции(архив)].podm = St!podm, [Станции(архив)].pech = St!pech, [Станции(архив)].arkt = St!arkt, [Станции(архив)].kuzn = St!kuzn, [Станции(архив)].ural = St!ural, [Станции(архив)].bashk = St!bashk, [Станции(архив)].kazah = St!kazah, [Станции(архив)].kan = St!kan, [Станции(архив)].tung = St!tung, [Станции(архив)].irkut = St!irkut, [Станции(архив)].hak = St!hak, [Станции(архив)].tuv = St!tuv, [Станции(архив)].bur = St!bur, [Станции(архив)].chit = St!chit, [Станции(архив)].yakut = St!yakut, [Станции(архив)].amur = St!amur, [Станции(архив)].urg = St!urg, [Станции(архив)].prim = St!prim, [Станции(архив)].mag = St!mag, [Станции(архив)].sah = St!sah, [Станции(архив)].kamch = St!kamch, [Станции(архив)].ushum = St!ushum, [Станции(архив)].qotr = St!qotr, [Станции(архив)].snk = St!snk, [Станции(архив)].SNT = St!snt, [Станции(архив)].ewtp = St!ewtp, [Станции(архив)].nt = St!nt, [Станции(архив)].NTsum = St!ntsum, [Станции(архив)].obor = St!obor, [Станции(архив)].ved = St!ved, [Станции(архив)].вед = St!вед, [Станции(архив)].obl = St!obl, [Станции(архив)].dep = St!dep, [Станции(архив)].oes = St!oes, [Станции(архив)].ees = St!ees, [Станции(архив)].er = St!er, [Станции(архив)].gk = St!gk, [Станции(архив)].be = St!be
WHERE ((([Станции(архив)].oes)=1) AND (([Станции(архив)].year)=2020));
